                { threshold: "2626400", rate: { num: "4", den: "100" } },
                { threshold: "4145200", rate: { num: "6", den: "100" } },
                { threshold: "5754200", rate: { num: "8", den: "100" } },
                { threshold: "7272400", rate: { num: "93", den: "1000" } }
