var param17 = (name) => ({ kind: "param", name });
var le = (left, right) => ({ kind: "cmp", op: "le", left, right });
var tableB = {
  kind: "or",
  args: [isStatus10("mfj"), isStatus10("hoh"), isStatus10("qss")]
};
