      // ≤$30,000 → $1,000/child
      tier2Max: { value: "4000000", type: "money" },
      // ≤$40,000 → $800
      tier3Max: { value: "5000000", type: "money" },
      // ≤$50,000 → $600
      tier4Max: { value: "6000000", type: "money" },
      // ≤$60,000 → $400
      tier5Max: { value: "8000000", type: "money" },
      // ≤$80,000 → $200; above: $0
      amount1: { value: "100000", type: "money" },
