      // $25,000 NC limit
      section179InvestmentLimit: { value: "20000000", type: "money" },
      // $200,000
      conservationCreditPct: { value: "25", type: "int" },
      // § 105-153.11 (TY2025-26 donations)
      claimOfRightFloor: { value: "300000", type: "money" }
