var flatBase = { kind: "max0", arg: fact36("stateTaxableIncome") };
function flatTax(args) {
  return {
    id: `us.${args.st}.income_tax`,
    version: args.version ?? 1,
    jurisdiction: `us.${args.st}`,
    title: `${args.name} income tax \u2014 TY2025 flat rate on state taxable income`,
    citation: { source: args.source, section: args.section, url: args.url, excerpt: args.excerpt },
    effectiveFrom: args.effectiveFrom ?? "2025-01-01",
    effectiveTo: args.effectiveTo ?? "2026-01-01",
    output: { type: "money" },
    parameters: args.parameters ?? {},
    formula: {
      kind: "roundToDollar",
      value: {
        kind: "brackets",
        base: flatBase,
        table: [{ threshold: "0", rate: { num: args.ratePctTimes100, den: "10000" } }]
      },
      mode: "half-up"
    }
  };
}
function noIncomeTax(st, name, excerpt, url) {
  return {
    id: `us.${st}.income_tax`,
    version: 1,
    jurisdiction: `us.${st}`,
    title: `${name} \u2014 no individual income tax (TY2025)`,
    citation: {
      source: `${name} law (no individual income tax)`,
      section: "n/a",
      url,
      excerpt
    },
    effectiveFrom: "2025-01-01",
    // structural: open-ended
    output: { type: "money" },
    formula: { kind: "money", cents: "0" }
  };
}
